import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-vertiginoso-efecto-del-vino', 'C',
 [dict(t=896, e=942, titulo='Una bebida espiritual, no espirituosa', txt='«Por un solo Espíritu fuimos todos bautizados en un solo cuerpo, sean judíos o griegos, sean esclavos o libres; y a todos se nos dio a beber de un mismo Espíritu». Interesante, ¿va?, que dice «se nos dio a beber». Está hablando de una bebida. Se nos dio a beber del Espíritu. Mire, allá le llaman bebida espirituosa, pero aquí está hablando de una bebida espiritual. No es lo mismo. Diga conmigo: no es lo mismo. Pero quiero que empecemos a ver algunas situaciones que las tenemos que comparar con lo que pasa allá afuera, y que no es lo mismo, porque es en sustancia espiritual.'),
  dict(t=1801, e=1836, titulo='Borrachos del amor de Cristo', txt='[…] usted que dice estar lleno del Espíritu Santo tiene que emborracharse del amor del Señor, y eso le va a ir quitando algunos inhibidores. Se va a sentir usted más libre: puede danzar, puede reír, puede gozar, gritar, llorar. Y si alguien nos mira de allá afuera y dice: «Uy, esos están locos o están borrachos», somos las dos cosas: locos por Cristo y borrachos del amor de Cristo en nosotros. Ese es el resultado de su amor.'),
  dict(t=3103, e=3152, titulo='En la mesa, Dios ve tu corazón', txt='Hoy el Señor lo que quiere es que usted se acerque a la mesa, y la mesa nos habla de comunión. Y esa comunión nos habla de que Dios nos ama. No le importa cómo eres. Ahí estaba Mefiboset, a quien le dijo: «Te vas a sentar todos los días de tu vida aquí conmigo en esta mesa y vas a tener comunión conmigo; va a ser tan hermosa la comunión, porque te voy a dar pan, te voy a dar vino, y yo no voy a ver tus piernas lisiadas; lo que voy a ver es tu corazón». El Señor, en esta Santa Cena, lo que va a venir a ver es su corazón; y aquel que entregue su corazón a Dios sinceramente, va a recibir un gozo tremendo.')],
 [dict(t=733, txt='Nosotros podemos tener muy confundidos los conceptos de lo que es gozo y recreación, que se van mezclando con otras cosas que son del espíritu y no necesariamente del alma o de la carne.'),
  dict(t=2268, txt='Es una necesidad decirle: «Señor, dame de tu vino. Derrama de tu vino sobre mi vida, alegra mi corazón».'),
  dict(t=2914, txt='Pidamos gozo. Nos conviene para este tiempo final. Si estamos contentos, ¿qué importa lo de allá afuera?')],
 ['¿Dónde has estado buscando alegría: en lo que ofrece el mundo o en la llenura del Espíritu Santo?',
  '¿Qué inhibiciones o complejos necesitas que el Señor te vaya quitando para adorarlo con libertad y gozo?',
  'Al acercarte a la mesa de la Santa Cena, ¿qué parte de tu corazón quieres entregarle sinceramente al Señor?'])
